SELECT CAST(COUNT(*) AS REAL) / (2009 - 2000 + 1) AS annual_avg_races
FROM races
WHERE date >= '2000-01-01' AND date <= '2009-12-31';

SELECT AVG(
    CAST(
        SUBSTR(r.fastestLapTime, 1, INSTR(r.fastestLapTime, ':') - 1) AS REAL
    ) * 60 +
    CAST(
        SUBSTR(r.fastestLapTime, INSTR(r.fastestLapTime, ':') + 1) AS REAL
    )
) AS avg_fastest_lap_seconds
FROM results r
JOIN drivers d ON r.driverId = d.driverId
WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton'
  AND r.fastestLapTime IS NOT NULL;
